import type { DemoData, Interval, Marker } from '../types';
import { markerWindow } from './markerAnalysis';

type Props = { data: DemoData; playhead: number; interval: Interval; highlighted: string[]; onMarker: (marker: Marker) => void; onHighlight: (id: string) => void; onData: () => void };
export default function RecordingExplorer({ data, playhead, interval, highlighted, onMarker, onHighlight, onData }: Props) {
  const next = data.events.find(e => e.timeSeconds > playhead);
  const selectedMarker = data.events.find(event => event.timeSeconds >= interval.start && event.timeSeconds < interval.end);
  const selectedMarkerWindow = selectedMarker ? markerWindow(selectedMarker, data.recording.durationSeconds) : null;
  const selectedMarkerHasRaw = selectedMarkerWindow ? selectedMarkerWindow.start >= data.detail.startSeconds && selectedMarkerWindow.end <= data.detail.endSeconds : false;
  const stats = useMemo(() => {
    try { const w = selectWindow(data, interval); return { resolution: w.resolution, ranges: w.channels.map(c => ({ id: c.id, name: c.name, range: Math.max(...c.values)-Math.min(...c.values) })) }; } catch { return null; }
  }, [data, interval]);
  const maximum = Math.max(.001, ...(stats?.ranges.map(r => r.range) ?? [1]));
  const leading = stats?.ranges.reduce((a, b) => b.range > a.range ? b : a);
  return <section className="explorer-panel" aria-label="Recording explorer">
    <header className="panel-heading"><div><h2>Recording explorer</h2><span>{data.recording.id}</span></div><button className="text-button" onClick={onData}>Source details <ArrowUpRight size={14}/></button></header>
    <div className="recording-title"><h1>{data.recording.sourceUrl.includes("21927431") ? "KUKA LWR4+" : data.recording.name}</h1><p>Recorded torque experiment <span>{data.channels.length} joints · {data.recording.durationSeconds.toFixed(0)} s · {data.recording.sampleRateHz} Hz source</span></p></div>
    <div className="explorer-body">
      <aside className="event-browser"><div className="section-label"><Flag size={12}/>All markers <span>{data.events.length}</span></div><div className="event-list" aria-label="All publisher markers">{data.events.map(e => <button key={e.id} onClick={() => onMarker(e)} className={`event-item ${e.timeSeconds >= interval.start && e.timeSeconds < interval.end ? 'selected' : ''}`}><span className="event-tick"/><span>{e.label}<small>{e.timeSeconds.toFixed(3)} s</small></span><ChevronRight size={13}/></button>)}{!data.events.length && <p className="quiet-empty">No publisher markers in this recording.</p>}</div>{next && <button className="text-button next-marker" onClick={() => onMarker(next)}>Next marker <ChevronRight size={13}/></button>}</aside>
      <div className="range-overview"><div className="range-title"><h3>Torque range</h3><span className="mono">{intervalLabel(interval)}</span></div><div className="range-bars" aria-label="Maximum minus minimum torque per joint">{data.channels.map((channel, i) => { const value = stats?.ranges[i]?.range; return <button key={channel.id} className={`range-row ${highlighted.includes(channel.id) ? 'active' : ''}`} onClick={() => onHighlight(channel.id)} aria-label={`Highlight ${channel.name}, range ${value?.toFixed(3) ?? 'unavailable'} Nm`}><span>J{i+1}</span><div className="bar-track"><div style={{ width: `${(value ?? 0)/maximum*100}%`, background: COLORS[i] }}/></div><span className="mono">{value?.toFixed(3) ?? '—'} <small>Nm</small></span></button>; })}</div><div className="range-caption">{leading ? <><span>{leading.name}</span> has the widest excursion in this interval.</> : 'Select a replayed interval to compare joints.'}</div></div>
    </div>
    <footer className="explorer-footer"><details className="marker-explainer"><summary><Info size={13}/><span>{selectedMarker ? `${selectedMarker.label} · marker details` : 'What is a marker?'}</span></summary><div className="marker-detail"><strong>{selectedMarker ? `${selectedMarker.label} at ${selectedMarker.timeSeconds.toFixed(3)} s` : 'Publisher event marker'}</strong><p>This timestamp comes from <span className="mono">{selectedMarker?.source ?? 'JK_moments'}</span>, the dataset publisher's manual event annotation. It helps navigate the recording, but it is not an independently verified exact collision onset.</p>{selectedMarker && <p className="marker-analysis-status">{selectedMarkerHasRaw ? 'Selecting it automatically runs measured analysis and OpenTSLM on the surrounding raw window.' : 'Selecting it automatically summarizes the available display samples. OpenTSLM requires the full-resolution window from the data adapter.'}</p>}{selectedMarker && <button className="text-button" onClick={() => onMarker(selectedMarker)}>Analyze its context <ChevronRight size={13}/></button>}</div></details><span className="data-resolution">{stats?.resolution === 'raw' ? 'Raw samples' : 'Display samples'}</span></footer>
  </section>;
}
import type { DemoData } from '../types';

export type PositionData = {
  recordingId: string; endSeconds?: number; angularUnit: 'radian'; sampleRateHz: number;
  times: number[]; joints: { channelId: string; values: number[] }[];
  validation: { mappingVerified: boolean; scope: string; conventionReference?: string; timestampsExactlyMatchTorque?: boolean; allAnglesWithinUrdfLimits?: boolean };
};

export function validatePositions(value: unknown, recordingId: string): asserts value is PositionData {
  const data = value as PositionData;
  if (!data || data.recordingId !== recordingId || data.angularUnit !== 'radian' || data.sampleRateHz !== 100 ||
    !(data.validation?.mappingVerified === true || (data.validation?.mappingVerified === false && data.validation.conventionReference === '05-28-21-25' && data.validation.timestampsExactlyMatchTorque === true && data.validation.allAnglesWithinUrdfLimits === true)) || typeof data.validation.scope !== 'string' || !data.validation.scope.trim() ||
    !Array.isArray(data.times) || !data.times.length ||
    data.times.some((t, i) => !Number.isFinite(t) || t < 0 || (i > 0 && (t <= data.times[i - 1] || Math.abs(t - data.times[i - 1] - 1 / data.sampleRateHz) > 1e-6))) ||
    (data.endSeconds !== undefined && (!Number.isFinite(data.endSeconds) || data.endSeconds < data.times[data.times.length - 1] || data.endSeconds > data.times[data.times.length - 1] + 1 / data.sampleRateHz + 1e-8)) ||
    !Array.isArray(data.joints) || data.joints.length !== 7 ||
    data.joints.some((joint, index) => joint?.channelId !== `joint_${index + 1}` || !Array.isArray(joint.values) || joint.values.length !== data.times.length || joint.values.some(angle => !Number.isFinite(angle)))) {
    throw new Error('Measured joint positions could not be validated.');
  }
}

/** Exact recorded articulation, held from the most recent sample; never a future sample. */
export function positionAtPlayhead(data: PositionData, recordingId: string, playhead: number) {
  if (data.recordingId !== recordingId || !Number.isFinite(playhead) || !data.times.length ||
    playhead < data.times[0] || playhead > (data.endSeconds ?? data.times[data.times.length - 1])) return null;
  let lo = 0, hi = data.times.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (data.times[mid] <= playhead) lo = mid + 1;
    else hi = mid;
  }
  if (!lo) return null;
  const index = lo - 1;
  return { time: data.times[index], radians: data.joints.map(joint => joint.values[index]) };
}

/** Sample-and-hold: never interpolate using a measurement after the playhead. */
export function torqueAtPlayhead(data: DemoData, playhead: number) {
  if (!Number.isFinite(playhead) || playhead < 0 || playhead > data.recording.durationSeconds) return null;
  const raw = playhead >= data.detail.startSeconds && playhead < data.detail.endSeconds;
  const source = raw ? data.detail : data;
  let lo = 0, hi = source.times.length;
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (source.times[mid] <= playhead) lo = mid + 1;
    else hi = mid;
  }
  if (!lo) return null;
  return {
    time: source.times[lo - 1],
    resolution: raw ? 'raw' as const : 'display' as const,
    channels: source.channels.map(c => ({ id: c.id, name: c.name, unit: c.unit, value: c.values[lo - 1] })),
  };
}

/** Only known fixtures are routed; never borrow another recording's pose. */
export function positionFixture(recordingId: string): string | undefined {
  if (recordingId === '05-28-21-25') return '/robot/kuka/positions.json';
  if (['03-15-12-53', '03-22-11-18', '05-28-20-57', '05-28-21-02', '05-28-21-07', '05-28-21-15'].includes(recordingId)) return `/robot/kuka/positions-${recordingId}.json`;
}

